import type { AppLanguage } from '@workspace/contracts';
import generatedLocales from './axterm-navigation.generated.json';

export interface LocaleDefinition {
  id: AppLanguage;
  name: string;
  flag: string;
  match: string;
  messages: Record<string, string>;
}

interface GeneratedLocaleData {
  schemaVersion: number;
  source: { project: string; catalog: string; reviewStatus: string };
  keyCount: number;
  locales: LocaleDefinition[];
}

const localeData = generatedLocales as GeneratedLocaleData;
const localeById = new Map(localeData.locales.map((locale) => [locale.id, locale]));
const englishMessages = localeById.get('en')!.messages;

